//! Golden replay: the Rust core must reproduce the TypeScript simulation.
//!
//! The fixture is generated by
//! `GOLDEN=1 pnpm vitest run tests/tools/golden.test.ts` in `web/`.

use gunbrawl_content::Content;
use gunbrawl_core::types::{
    ActorConfig, ActorInput, ActorStatus, Control, DropMode, GameMode, InputTable, MatchConfig,
};
use gunbrawl_core::{Simulation, FIXED_STEP};
use serde::Deserialize;

const FIXTURE: &str = include_str!("../../core/tests/fixtures/golden.json");
const TOLERANCE: f64 = 1e-3;

#[derive(Deserialize)]
struct Fixture {
    #[serde(rename = "scriptSeed")]
    script_seed: u32,
    samples: Vec<Sample>,
}

#[derive(Deserialize)]
struct Sample {
    frame: usize,
    phase: u8,
    projectiles: usize,
    actors: Vec<SampleActor>,
}

#[derive(Deserialize)]
struct SampleActor {
    x: f64,
    y: f64,
    stocks: i32,
    status: String,
}

struct Script {
    state: u32,
}

impl Script {
    fn new(seed: u32) -> Self {
        Self { state: seed }
    }

    fn next(&mut self) -> f64 {
        self.state = self
            .state
            .wrapping_mul(1_664_525)
            .wrapping_add(1_013_904_223);
        self.state as f64 / 4_294_967_296.0
    }

    fn input(&mut self) -> ActorInput {
        let move_roll = self.next();
        let jump = self.next();
        let drop = self.next();
        let fire = self.next();
        let bomb = self.next();
        let reload = self.next();
        ActorInput {
            move_x: if move_roll < 0.34 {
                -1
            } else if move_roll < 0.67 {
                0
            } else {
                1
            },
            jump_pressed: jump < 0.08,
            drop_pressed: drop < 0.03,
            shoot_held: fire < 0.55,
            bomb_pressed: bomb < 0.02,
            reload_pressed: reload < 0.02,
        }
    }
}

fn phase_code(phase: gunbrawl_core::types::MatchPhase) -> u8 {
    use gunbrawl_core::types::MatchPhase::*;
    match phase {
        Countdown => 0,
        Playing => 1,
        Paused => 2,
        Finished => 3,
    }
}

fn status_code(status: ActorStatus) -> &'static str {
    match status {
        ActorStatus::Alive => "alive",
        ActorStatus::Respawning => "respawning",
        ActorStatus::Eliminated => "eliminated",
    }
}

fn build_config(content: &Content) -> MatchConfig {
    let pistol = content.pistol();
    let actors = (0..4)
        .map(|index| ActorConfig {
            id: index as u8,
            name: format!("P{}", index + 1),
            color: 0xffffff,
            control: Control::Human((index % 2) as u8 + 1),
        })
        .collect();
    MatchConfig {
        mode: GameMode::Custom,
        map: content.map("sky-citadel").expect("sky-citadel").clone(),
        weapons: content.weapons.clone(),
        actors,
        starting_weapon: pistol,
        pistol,
        stocks: 3,
        duration: 180.0,
        countdown: 0.0,
        seed: 42,
        drop_mode: DropMode::All,
    }
}

#[test]
fn reproduces_the_typescript_simulation() {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("fixture parses");
    let content = Content::parse().expect("content parses");
    let mut simulation = Simulation::new(build_config(&content), content.drop_pool(DropMode::All));
    let mut script = Script::new(fixture.script_seed);

    for sample in &fixture.samples {
        let mut inputs: InputTable = [None; 4];
        for slot in inputs.iter_mut() {
            *slot = Some(script.input());
        }
        simulation.step(FIXED_STEP, &inputs);

        assert_eq!(
            phase_code(simulation.state.phase),
            sample.phase,
            "phase mismatch at frame {}",
            sample.frame
        );
        assert_eq!(
            simulation.state.projectiles.len(),
            sample.projectiles,
            "projectile count mismatch at frame {}",
            sample.frame
        );
        assert_eq!(
            simulation.state.actors.len(),
            sample.actors.len(),
            "actor count mismatch at frame {}",
            sample.frame
        );
        for (index, expected) in sample.actors.iter().enumerate() {
            let actual = &simulation.state.actors[index];
            let dx = (actual.position.x - expected.x).abs();
            let dy = (actual.position.y - expected.y).abs();
            assert!(
                dx <= TOLERANCE && dy <= TOLERANCE,
                "frame {} actor {}: expected ({}, {}), got ({}, {}) delta ({dx}, {dy})",
                sample.frame,
                index,
                expected.x,
                expected.y,
                actual.position.x,
                actual.position.y
            );
            assert_eq!(
                actual.stocks, expected.stocks,
                "stocks mismatch at frame {} actor {}",
                sample.frame, index
            );
            assert_eq!(
                status_code(actual.status),
                expected.status,
                "status mismatch at frame {} actor {}",
                sample.frame,
                index
            );
        }
    }

    assert!(!fixture.samples.is_empty());
}
